import csv, json, os, re, shutil, tempfile, zipfile
import xml.etree.ElementTree as ET

SRC_HWPKG = '/root/renewal_playbook.hwpx'
UPDATE_JSON = '/root/renewal_update.json'
FOLLOWUPS_CSV = '/root/followups.csv'
OUT_HWPKG = '/root/renewal_playbook_updated.hwpx'

HP_LOCAL_CACHE_NAMES = {
    'linesegarray','lineSegArray','linesegArray','lineseg','lineSeg'
}

def localname(tag: str) -> str:
    return tag.split('}',1)[1] if tag.startswith('{') and '}' in tag else tag


def collect_namespaces(xml_path: str):
    ns = []
    for event, data in ET.iterparse(xml_path, events=('start-ns',)):
        prefix, uri = data
        ns.append((prefix if prefix is not None else '', uri))
    # de-dup, keep first occurrence
    seen = set()
    out = []
    for p,u in ns:
        if (p,u) in seen: continue
        seen.add((p,u))
        out.append((p,u))
    return out


def register_namespaces(ns_list):
    for prefix, uri in ns_list:
        ET.register_namespace(prefix, uri)


def paragraph_text(p):
    # Join all <...:t> under this paragraph, in document order
    parts = []
    for node in p.iter():
        if localname(node.tag) == 't':
            parts.append(node.text or '')
    return ''.join(parts)


def remove_descendants_by_localnames(elem, names_set):
    # remove matching descendants, including direct children
    stack = [elem]
    while stack:
        parent = stack.pop()
        for child in list(parent):
            if localname(child.tag) in names_set:
                parent.remove(child)
            else:
                stack.append(child)


def set_paragraph_text_collapse_runs(p, text):
    # Collapse paragraph to a single <run><t>text</t></run> preserving first run attrs.
    uri = None
    if p.tag.startswith('{'):
        uri = p.tag[1:].split('}',1)[0]
    run_tag = f'{{{uri}}}run' if uri else 'run'
    t_tag = f'{{{uri}}}t' if uri else 't'

    children = list(p)
    runs = [c for c in children if c.tag == run_tag]

    if runs:
        first_run = runs[0]
    else:
        first_run = ET.Element(run_tag)
        p.insert(0, first_run)

    t = first_run.find(t_tag)
    if t is None:
        # remove all children first to avoid mixed content
        for c in list(first_run):
            first_run.remove(c)
        t = ET.SubElement(first_run, t_tag)
    else:
        # remove siblings of t inside the run
        for c in list(first_run):
            if c is not t:
                first_run.remove(c)

    t.text = text

    # remove all other run elements under paragraph
    for r in list(p):
        if r is first_run:
            continue
        if r.tag == run_tag:
            p.remove(r)


with open(UPDATE_JSON, 'r', encoding='utf-8') as f:
    upd = json.load(f)

customer = upd['customer']
owner_name = upd['owner_name']
window_start = upd['window_start']
window_end = upd['window_end']
band = upd['band']
escalation_email = upd['escalation_email']
note = upd['note']

followups = []
with open(FOLLOWUPS_CSV, 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if not row: continue
        followups.append((int(row['sequence']), row['item']))
followups.sort(key=lambda x: x[0])
followup_map = {seq: item for seq, item in followups}

# Expect sequences 1..3
for expected in (1,2,3):
    if expected not in followup_map:
        raise SystemExit(f"Missing follow-up sequence {expected} in CSV")

with tempfile.TemporaryDirectory() as td:
    with zipfile.ZipFile(SRC_HWPKG, 'r') as zin:
        zin.extractall(td)
        infos = zin.infolist()

    # Discover old values by parsing section0.xml and reading relevant paragraphs
    sec0_path = os.path.join(td, 'Contents', 'section0.xml')
    ns0 = collect_namespaces(sec0_path)
    register_namespaces(ns0)
    t0 = ET.parse(sec0_path)
    r0 = t0.getroot()

    old_customer = old_owner = old_window_range = old_band = old_escalation = old_note = None

    for p in r0.iter():
        if localname(p.tag) != 'p':
            continue
        txt = paragraph_text(p).strip()
        if txt.startswith('고객사:'):
            old_customer = txt.split('고객사:',1)[1].strip()
        elif txt.startswith('현 담당자:'):
            old_owner = txt.split('현 담당자:',1)[1].strip()
        elif txt.startswith('갱신 윈도우:'):
            old_window_range = txt.split('갱신 윈도우:',1)[1].strip()
        elif txt.startswith('가격 메모:'):
            old_note = txt.split('가격 메모:',1)[1].strip()

    # For band/escalation, they are in a table cell paragraph without prefix
    for p in r0.iter():
        if localname(p.tag) != 'p':
            continue
        txt = paragraph_text(p).strip()
        if txt and txt == 'Standard-18M':
            old_band = txt
        if txt and re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", txt):
            # first email in section0 is escalation
            if old_escalation is None:
                old_escalation = txt

    missing = [k for k,v in {
        'old_customer': old_customer,
        'old_owner': old_owner,
        'old_window_range': old_window_range,
        'old_band': old_band,
        'old_escalation': old_escalation,
        'old_note': old_note,
    }.items() if v is None]
    if missing:
        raise SystemExit('Could not detect old values: ' + ', '.join(missing))

    appendix_sentence = '이 부록 문단은 그대로 유지해야 합니다.'

    modified_paras = []  # (xml_path, p_id)

    def process_xml(xml_path: str):
        ns = collect_namespaces(xml_path)
        register_namespaces(ns)
        tree = ET.parse(xml_path)
        root = tree.getroot()

        # track appendix existence in section1
        appendix_found = False

        for p in root.iter():
            if localname(p.tag) != 'p':
                continue
            before = paragraph_text(p)
            after = before

            # follow-ups replacement
            m = re.match(r"^\s*([1-3])\.\s*(.*)$", before)
            if m and 'old follow-up' in before:
                n = int(m.group(1))
                after = f"{n}. {followup_map[n]}"

            # field replacements (do range first so we don't accidentally replace date fragments)
            if old_window_range in after:
                after = after.replace(old_window_range, f"{window_start} ~ {window_end}")
            if old_customer in after:
                after = after.replace(old_customer, customer)
            if old_owner in after:
                after = after.replace(old_owner, owner_name)
            if old_band in after:
                after = after.replace(old_band, band)
            if old_escalation in after:
                after = after.replace(old_escalation, escalation_email)
            if old_note in after:
                after = after.replace(old_note, note)

            if appendix_sentence in before:
                appendix_found = True
                # ensure we never modify it
                if after != before:
                    raise SystemExit(f"Appendix sentence paragraph was modified unexpectedly in {xml_path}")

            if after != before:
                # Update paragraph text and remove layout cache
                set_paragraph_text_collapse_runs(p, after)
                remove_descendants_by_localnames(p, HP_LOCAL_CACHE_NAMES)
                pid = p.attrib.get('id', '')
                modified_paras.append((os.path.basename(xml_path), pid))

        # additional safeguard: ensure appendix present in doc at least once
        if os.path.basename(xml_path) == 'section1.xml' and not appendix_found:
            raise SystemExit('Appendix sentence not found in section1.xml')

        tree.write(xml_path, encoding='UTF-8', xml_declaration=True)

    for name in os.listdir(os.path.join(td, 'Contents')):
        if name.lower().endswith('.xml'):
            process_xml(os.path.join(td, 'Contents', name))

    # Verify no old values remain in any XML content.
    old_markers = [old_customer, old_owner, old_window_range, old_band, old_escalation, old_note,
                   'old follow-up alpha', 'old follow-up beta', 'old follow-up gamma']

    for name in os.listdir(os.path.join(td, 'Contents')):
        if not name.lower().endswith('.xml'):
            continue
        path = os.path.join(td, 'Contents', name)
        data = open(path,'r',encoding='utf-8').read()
        for marker in old_markers:
            if marker and marker in data:
                raise SystemExit(f"Found stale marker '{marker}' in {name}")

    # Verify appendix unchanged
    sec1 = open(os.path.join(td, 'Contents','section1.xml'),'r',encoding='utf-8').read()
    if appendix_sentence not in sec1:
        raise SystemExit('Appendix sentence missing after modifications')

    # Repackage
    if os.path.exists(OUT_HWPKG):
        os.remove(OUT_HWPKG)

    with zipfile.ZipFile(OUT_HWPKG, 'w', compression=zipfile.ZIP_DEFLATED) as zout:
        # preserve original file order
        for info in infos:
            arc = info.filename
            src_path = os.path.join(td, arc)
            if os.path.isdir(src_path):
                continue
            zout.write(src_path, arcname=arc)

print('Wrote', OUT_HWPKG)
print('Modified paragraphs:', len(modified_paras))
for x in modified_paras:
    print(' -', x)
